<?php require_once __DIR__.'/../auth.php';require_admin();
function scalar_count(mysqli $conn,string $sql):int{$r=$conn->query($sql)->fetch_row();return (int)$r[0];}
$students=scalar_count($conn,'SELECT COUNT(*) FROM students');$admins=scalar_count($conn,"SELECT COUNT(*) FROM students WHERE role='admin'");$events=scalar_count($conn,'SELECT COUNT(*) FROM events');$regs=scalar_count($conn,'SELECT COUNT(*) FROM registrations');
$latest=$conn->query('SELECT student_id,name,email,role,created_at FROM students ORDER BY created_at DESC LIMIT 8');$logs=$conn->query('SELECT a.action,a.details,a.ip_address,a.created_at,s.name FROM audit_logs a LEFT JOIN students s ON s.student_id=a.student_id ORDER BY a.created_at DESC LIMIT 12');
page_start('Practical 14 — Admin Dashboard');?>
